//! Four sessions of the owner's live tests, made by a script (kept
//! outside the repository) from
//! experiments/bt-gamepad-test/logs/live1.log and live3.log.
//! Device data, not code. No address: the 0x21 report's masked
//! address bytes are a made-up one (a6 a5 a4 a3 a2 a1).
//!
//! What the logs hold byte for byte: the SDP answers (whole PDUs),
//! the input reports they printed (the first 20, every change, and
//! one a second), every output report. What they hold only as
//! decoded fields: HCI events, L2CAP signalling, ACL framing.
#![allow(dead_code)]

pub struct Session {
    pub name: &'static str,
    pub cod: u32,
    /// The SDP answer PDU for the HID query, hex.
    pub sdp_hid: &'static str,
    /// The SDP answer PDU for the Device ID query, hex.
    pub sdp_pnp: &'static str,
    /// Input reports in the order they came (without 0xA1), hex.
    pub reports: &'static [&'static str],
    /// Output reports the firmware sent: "kind:hex".
    pub outputs: &'static [&'static str],
    pub end_reason: Option<u8>,
    /// How far the link got (the PAD-SUMMARY end line).
    pub reached: &'static str,
}

/// Switch mode, live3: the pad calls, then hangs up after SDP.
pub const SWITCH_FAILS: Session = Session {
    name: "Pro Controller",
    cod: 0x002508,
    sdp_hid: "",
    sdp_pnp: "",
    reports: &[],
    outputs: &[],
    end_reason: Some(0x13),
    reached: "hid-open",
};

